set -u; echo '### ДОВАНТАЖУЮ ВСІ КОПІЇ'; rclone copy /root/backups/ gdrive:unitex-backups/ 2>&1 | tail -3; echo '### ЗВІРКА СЕРВЕР vs DRIVE'; rclone check /root/backups/ gdrive:unitex-backups/ --size-only 2>&1 | tail -3; echo '### ЩО ТЕПЕР НА DRIVE'; rclone ls gdrive:unitex-backups/ 2>&1; echo '### === ГОЛОВНЕ: ВІДНОВЛЕННЯ З GOOGLE DRIVE ==='; D=/root/gdrive-restore-test; mkdir -p $D; F=$(rclone lsf gdrive:unitex-backups/ 2>/dev/null | sort | tail -1); echo "беру з Drive: $F"; rclone copy "gdrive:unitex-backups/$F" $D/ 2>&1 | tail -2; ls -la $D/; echo '--- розшифровую'; gpg --batch --yes --quiet --passphrase-file /root/.backup-pass -o $D/a.tar.gz -d "$D/$F" && echo '  розшифровано'; tar -xzf $D/a.tar.gz -C $D && echo '  розпаковано'; echo '--- перевіряю базу з Drive'; python3 -c '
import sqlite3,sys,os
b=sqlite3.connect(os.path.join(sys.argv[1],"noco.db"))
Q=chr(34)
print("  цілість:", b.execute("PRAGMA integrity_check").fetchone()[0])
for t in ["nc_bpfs___\u0414\u0438\u0441\u043f\u0435\u0442\u0447\u0435\u0440\u0438\u0437\u0430\u0446\u0456\u044f","nc_bpfs___audit_log","nc_bpfs___\u041a\u043b\u0456\u0454\u043d\u0442\u0438"]:
    try: print("  %-30s %d" % (t, b.execute("SELECT COUNT(*) FROM "+Q+t+Q).fetchone()[0]))
    except Exception as e: print("  %s: %s" % (t, str(e)[:40]))
b.close()
' $D 2>&1 | head -6; echo '--- службові файли з Drive:'; ls -1 $D/config 2>/dev/null | wc -l; echo "тека тесту: $D (лишаю)"
